var cellSide = 1;
var options = {units: 'kilometers'};
var squareGrid = turf.squareGrid(bbox, cellSide, options).features.map(function(feature, index) {
    feature.properties = { id: index }; // Add property with sequential ID
    return feature;
});

// Extract IDs into an array
