          event_data: null,
          fn_index: 1,
          trigger_id: 10,
          session_hash: sessionHash
        })
      });

      if (!joinResponse.ok) {
        return new Response('Failed to initiate video generation', { status: 502 });
      }

      // Step 2: Poll the streaming data endpoint until process_completed with success
      let videoUrl = null;
      const maxAttempts = 60; // max polling attempts (~60 seconds)
      let attempts = 0;

      while (attempts < maxAttempts) {
        const dataResponse = await fetch(`https://bytedance-animatediff-lightning.hf.space/queue/data?session_hash=${sessionHash}`);

        if (!dataResponse.ok) {
          return new Response('Failed to fetch generation status', { status: 502 });
        }

        // The response is streamed with lines starting with "data: ", so parse accordingly
        const text = await dataResponse.text();

        // Split by lines and parse JSON from lines starting with "data: "
        const lines = text.split('\n').filter(line => line.startsWith('data: '));

        for (const line of lines) {
          const jsonStr = line.slice(6).trim();
          if (!jsonStr) continue;

          let parsed;
          try {
            parsed = JSON.parse(jsonStr);
          } catch (e) {
            continue; // skip invalid JSON lines
          }

          if (parsed.msg === 'process_completed' && parsed.success) {
            videoUrl = parsed.output.data[0].video.url;
            break;
          }
        }

        if (videoUrl) {
          break;
        }

        // Wait 1 second before next poll
        await new Promise(resolve => setTimeout(resolve, 1000));
        attempts++;
      }

      if (!videoUrl) {
        return new Response('Video generation timed out', { status: 504 });
      }

      // Return the video URL as JSON
      return new Response(JSON.stringify({ videoUrl }), {
        status: 200,
        headers: { 'Content-Type': 'application/json' }
      });

    } catch (error) {
      return new Response('Internal Server Error', { status: 500 });
    }
  } else {
    return new Response('Not Found', { status: 404 });
  }
}

function generateRandomSessionHash() {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  let hash = '';
  for (let i = 0; i < 12; i++) {
    hash += chars[Math.floor(Math.random() * chars.length)];
  }
  return hash;
